import{_ as n,a0 as s,w as l,s as p,ao as o,I as r,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 Cream 提高 Vim 的用户友好性 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Cream 提高 Vim 的用户友好性 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Cream 提高 Vim 的用户友好性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Cream 提高 Vim 的用户友好性 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170518 How to make Vim user-friendly with Cream","title":"如何使用 Cream 提高 Vim 的用户友好性","tag":"201705","desc":""},"relativePath":"201705/20170518 How to make Vim user-friendly with Cream.md","filePath":"[post].md"}'),C={name:"201705/20170518 How to make Vim user-friendly with Cream.md"};function u(d,e,f,V,g,T){const m=s("Link");return l(),p("div",null,[e[19]||(e[19]=o('<h1 id="如何使用-cream-提高-vim-的用户友好性" tabindex="-1">如何使用 Cream 提高 Vim 的用户友好性 <a class="header-anchor" href="#如何使用-cream-提高-vim-的用户友好性" aria-label="Permalink to “如何使用 Cream 提高 Vim 的用户友好性”">​</a></h1><blockquote><p>Cream 附加包通過把一個更加熟悉的“面孔”置於 Vim 文本編輯器之上，同時保留 Vim 的功能，使其更加容易使用</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/education/osdc_edu_rightmix_520.png?itok=SCsog_qv" alt="How to make Vim user-friendly with Cream" title="How to make Vim user-friendly with Cream"></p><p>圖片來自 : opensource.com</p><p>大約 10 年前，我既使用 Emacs 進行文本編輯，也使用 Vim 進行文本編輯。説到底，我的確是一個熱衷於 Emacs 的傢伙。儘管 Emacs 在我的心裏佔據了很重要的地位，但我知道， Vim 也不賴。</p><p>一些人，或者像我一樣的人，在技術方面有些笨手笨腳。多年來，我和一些 Linux 新手交流，瞭解到他們想使用 Vim，但是卻失望的發現， Vim 編輯器和他們在其它操作系統上使用過的編輯器不一樣。</p><p>但是，當我把 Cream 介紹給他們以後，他們的失望就變成了滿意。Cream 是 Vim 的一個附加包，它使得 Vim 更加容易使用。Cream 讓這些 Linux 新手變成了 Vim 的堅決擁護者和忠心用户。</p><p>讓我們來看一看 Cream 是什麼以及它是如何讓 Vim 變得更加容易使用的。</p><h3 id="cream-的安裝" tabindex="-1">Cream 的安裝 <a class="header-anchor" href="#cream-的安裝" aria-label="Permalink to “Cream 的安裝”">​</a></h3><p>在安裝 Cream 之前，你需要先在你的電腦上安裝好 Vim 和 GVim 的 GUI 組件。我發現最容易完成這件事的方法是使用 Linux 版本的包管理器。</p>',10)),r("p",null,[e[1]||(e[1]=t("安裝好 Vim 以後，便可",-1)),i(m,{href:"http://cream.sourceforge.net/download.html"},{default:a(()=>[...e[0]||(e[0]=[t("下載 Cream 的安裝程序",-1)])]),_:1}),e[2]||(e[2]=t("，或者你也可以再次使用 Linux 發行版的包管理器進行安裝。",-1))]),e[20]||(e[20]=o('<p>安裝好 Cream 以後，你可以從應用菜單選擇它（比如，<strong>Applications</strong>-&gt;<strong>Cream</strong>）或者在程序啓動器中輸入 <code>Cream</code>，從而啓動 Cream 。</p><p><img src="https://opensource.com/sites/default/files/resize/cream-main-window-520x336.png" alt="Cream’s main window" title="Cream’s main window"></p><h3 id="cream-的使用" tabindex="-1">Cream 的使用 <a class="header-anchor" href="#cream-的使用" aria-label="Permalink to “Cream 的使用”">​</a></h3><p>如果你之前已經使用過 Gvim，那麼你會注意到， Cream 幾乎沒改變該編輯器的外觀和感覺。最大的不同是 Cream 的菜單欄和工具欄，它們取代了 Gvim 陳舊的菜單欄和工具欄，新的菜單欄和工具欄的外觀和功能分組看起來和其它編輯器的一樣。</p><p>Cream 的菜單欄對用户隱藏了更多的技術選項，比如指定一個編譯器的能力，以及運行 <code>make</code> 命令的能力。當你通過使用 Cream 更加熟悉 Vim 以後，你只需要從 <strong>Setting</strong>-&gt;<strong>Preferences</strong>-&gt;<strong>Behavior</strong> 選擇選項，就可以更容易地訪問這些特性。有了這些選項，你可以（如果你想）體驗到一個兼有 Cream 和傳統 Vim 二者優點的強大編輯器。</p><p>Cream 並不是僅由菜單驅動。儘管編輯器的功能僅有單擊或雙擊兩種方式，但是你也可以使用常見的鍵盤快捷鍵來執行操作，比如 <code>CTRL-O</code>（打開一個文件），<code>CTRL-C</code>（複製文本）。你不需要在幾種模式之間切換，也不需要記住一些很難記住的命令。</p><p>Cream 開始運行以後，打開一個文件，或者新建一個文件，然後就可以開始輸入了。幾個我向他們介紹過 Cream 的人説，雖然 Cream 保留了 Vim 的許多典型風格，但是 Cream 使用起來更加舒服。</p><p><img src="https://opensource.com/sites/default/files/cream-in-action.png" alt="Cream add-on for VIM in action" title="Cream add-on for VIM in action"></p>',8)),r("p",null,[e[4]||(e[4]=t("並不是説 Cream 是 Vim 的簡化版，遠遠不是。事實上， Cream 保留了 Vim 的全部特性，同時，它還有",-1)),i(m,{href:"http://cream.sourceforge.net/featurelist.html"},{default:a(()=>[...e[3]||(e[3]=[t("一系列其他有用的特性",-1)])]),_:1}),e[5]||(e[5]=t("。我發現的 Cream 的一些有用的特性包括：",-1))]),e[21]||(e[21]=r("ul",null,[r("li",null,"一個標籤式界面"),r("li",null,"語法高亮（特別是針對 Markdown、LaTeX 和 HTML）"),r("li",null,"自動修正拼寫錯誤"),r("li",null,"字數統計"),r("li",null,"內建文件瀏覽器")],-1)),e[22]||(e[22]=r("p",null,"Cream 本身也有許多附加包，可以給編輯器增加一些新的特性。這些特性包括文本加密、清理電子郵件內容，甚至還有一個使用教程。老實説，我還沒有發現哪一個附加包是真正有用的，不過你的感受可能會有所不同。",-1)),e[23]||(e[23]=r("p",null,"我曾聽過一些 Vi/Vim 的狂熱分子譴責 Cream “降低”（這是他們的原話）了 Vi/Vim 編輯器的水準。的確，Cream 並不是為他們設計的。它是為那些想快速使用 Vim ，同時保留他們曾經使用過的編輯器的外觀和感覺的人準備的。在這種情況下， Cream 是值得讚賞的，它使得 Vim 更加容易使用，更加廣泛的被人們使用。",-1)),e[24]||(e[24]=r("hr",null,null,-1)),r("p",null,[e[7]||(e[7]=t("via: ",-1)),i(m,{href:"https://opensource.com/article/17/5/stir-bit-cream-make-vim-friendlier"},{default:a(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/17/5/stir-bit-cream-make-vim-friendlier",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=t("作者：",-1)),i(m,{href:"https://opensource.com/users/scottnesbitt"},{default:a(()=>[...e[8]||(e[8]=[t("Scott Nesbitt",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),i(m,{href:"https://github.com/ucasFL"},{default:a(()=>[...e[9]||(e[9]=[t("ucasFL",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),i(m,{href:"https://github.com/jasminepeng"},{default:a(()=>[...e[10]||(e[10]=[t("jasminepeng",-1)])]),_:1})]),r("p",null,[e[16]||(e[16]=t("本文由 ",-1)),i(m,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創編譯，",-1)),i(m,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const L=n(C,[["render",u]]);export{x as __pageData,L as default};
